<?php get_header(); ?><main id="primary" class="sd-main"><div class="sd-container sd-content-wrap"><header class="sd-page-header"><h1><?php the_archive_title(); ?></h1><p><?php the_archive_description(); ?></p></header><?php if ( have_posts() ) : ?><div class="sd-grid sd-grid-3"><?php while ( have_posts() ) : the_post(); ?><article class="sd-card sd-card-body"><div class="sd-breadcrumbs"><?php echo esc_html( get_the_date() ); ?></div><h2><a href="<?php the_permalink(); ?>"><?php the_title(); ?></a></h2><p><?php echo esc_html( wp_trim_words( get_the_excerpt(), 24 ) ); ?></p></article><?php endwhile; ?></div><?php the_posts_pagination(); ?><?php else : sd_render_empty( __( 'No posts found', 'social-discovery' ), __( 'There is nothing to show here yet.', 'social-discovery' ) ); endif; ?></div></main><?php get_footer(); ?>
